    """Shear non-background cells left according to row position.

    Each occupied cell in row r moves left by (last occupied row - r)
    columns. Cells shifted outside the canvas are clipped.
    """
    h, w = len(grid), len(grid[0])
    occupied_rows = [r for r, row in enumerate(grid) if any(v != 0 for v in row)]
    if not occupied_rows:
        return [row[:] for row in grid]
    anchor = max(occupied_rows)
    out = [[0] * w for _ in range(h)]
    for r, row in enumerate(grid):
        shift = r - anchor
        for c, value in enumerate(row):
            if value != 0:
                nc = c + shift
                if 0 <= nc < w:
                    out[r][nc] = value
    return out
